<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>订阅访问分析</title><style>
:root{--ink:#15202b;--muted:#65727e;--line:#d9e0e6;--bg:#f4f6f8;--paper:#fff;--teal:#116466;--red:#b42318}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px Arial,sans-serif}.shell{max-width:1440px;margin:auto;padding:24px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px}.top h1{font-size:25px;margin:0}.top p{margin:5px 0 0;color:var(--muted)}button,input,select{font:inherit;border:1px solid var(--line);border-radius:4px;padding:8px;background:#fff}button{cursor:pointer;font-weight:600}.primary{background:var(--teal);border-color:var(--teal);color:#fff}.filters,.grid,.table-wrap{background:var(--paper);border:1px solid var(--line);margin-top:18px}.filters{padding:14px;display:flex;flex-wrap:wrap;gap:10px;align-items:end}.filters label{display:grid;gap:5px;font-size:12px;color:var(--muted)}.filters input,.filters select{min-width:110px;color:var(--ink)}.stats{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:10px;margin-top:18px}.stat{background:var(--paper);border:1px solid var(--line);padding:14px}.stat b{font-size:25px;display:block;margin-top:7px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0}.risk{padding:15px;border-bottom:1px solid var(--line)}.risk:nth-child(odd){border-right:1px solid var(--line)}h2{font-size:15px;margin:0 0 11px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{padding:8px;text-align:left;border-bottom:1px solid #edf0f2;vertical-align:top}th{color:var(--muted);font-weight:600}.table-wrap{overflow:auto}.badge{padding:2px 6px;border-radius:10px;background:#e6f4f4;color:#075a5d}.risk-badge{background:#fce8e7;color:var(--red)}.user-agent{min-width:320px;max-width:480px;overflow-wrap:anywhere;font-family:ui-monospace,SFMono-Regular,Consolas,monospace}.pager{display:flex;gap:8px;align-items:center;padding:12px}.state{padding:22px;color:var(--muted)}@media(max-width:760px){.shell{padding:15px}.stats{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.risk:nth-child(odd){border-right:0}.filters label{width:calc(50% - 5px)}.filters input,.filters select{min-width:0;width:100%}}
</style></head><body><main class="shell"><header class="top"><div><h1>订阅访问分析</h1><p>从订阅伪装审计记录中定位异常共享与代理访问。</p></div><button id="logout">退出</button></header>
<form id="filters" class="filters"><label>开始日期<input name="start" type="date"></label><label>结束日期<input name="end" type="date"></label><label>邮箱<input name="email" placeholder="包含文本"></label><label>IP<input name="ip" placeholder="精确 IP"></label><label>国家<input name="country" maxlength="2" placeholder="US"></label><label>命中原因<input name="reason"></label><label>User-Agent<input name="user_agent" placeholder="客户端关键字"></label><label>最小风险分<input name="min_fraud_score" type="number" min="0" max="100"></label><label><span>仅代理</span><select name="proxy_only"><option value="">全部</option><option value="1">是</option></select></label><label><span>仅伪装</span><select name="masked_only"><option value="">全部</option><option value="1">是</option></select></label><button class="primary">应用筛选</button></form>
<section class="stats" id="stats"></section><section class="grid" id="risks"></section><section class="table-wrap"><h2 style="padding:15px 15px 0">原始记录</h2><div id="state" class="state">正在加载记录...</div><table id="logs" hidden><thead><tr><th>时间</th><th>用户</th><th>IP / 国家</th><th>网络风险</th><th>User-Agent</th><th>规则</th><th>结果</th></tr></thead><tbody></tbody></table><div class="pager"><button id="prev">上一页</button><span id="page"></span><button id="next">下一页</button></div></section></main>
<script>
const f=document.querySelector('#filters'),stats=document.querySelector('#stats'),risks=document.querySelector('#risks'),table=document.querySelector('#logs'),body=table.querySelector('tbody'),state=document.querySelector('#state'),pageText=document.querySelector('#page');let page=1,total=0,size=50;
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const metric={total_requests:'请求总数',distinct_users:'独立用户',distinct_ips:'独立 IP',masked_requests:'伪装命中',proxy_requests:'代理请求',high_risk_requests:'高风险请求'};
function risk(title,rows,cols){return '<article class="risk"><h2>'+title+'</h2><table><thead><tr>'+cols.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+(rows.length?rows.map(r=>'<tr>'+cols.map(c=>'<td>'+escape(r[c.key])+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="'+cols.length+'">无异常记录</td></tr>')+'</tbody></table></article>'}
const dataUrl='{{ $analysisBaseUrl }}/data',logoutUrl='{{ $analysisBaseUrl }}/logout';async function load(){const q=new URLSearchParams(new FormData(f));q.set('page',page);q.set('page_size',size);state.hidden=false;state.textContent='正在加载记录...';table.hidden=true;const r=await fetch(dataUrl+'?'+q,{credentials:'same-origin'});if(r.status===401){location.href='{{ $analysisBaseUrl }}';return}if(!r.ok){state.textContent=(await r.json()).message||'加载失败';return}const d=await r.json();stats.innerHTML=Object.entries(metric).map(([k,l])=>'<div class="stat"><span>'+l+'</span><b>'+escape(d.summary[k])+'</b></div>').join('');risks.innerHTML=risk('共享 IP',d.suspicion.shared_ips,[{key:'ip'},{key:'distinct_users'},{key:'request_count'}])+risk('同用户多 IP',d.suspicion.multi_ip_users,[{key:'email'},{key:'distinct_ips'},{key:'request_count'}])+risk('跨国用户',d.suspicion.multi_country_users,[{key:'email'},{key:'distinct_countries'},{key:'request_count'}])+risk('高频用户 / IP',d.suspicion.high_frequency_pairs,[{key:'email'},{key:'ip'},{key:'request_count'}])+risk('共享 User-Agent',d.suspicion.shared_user_agents,[{key:'user_agent'},{key:'distinct_users'},{key:'distinct_ips'},{key:'request_count'}]);body.innerHTML=d.logs.data.map(x=>'<tr><td>'+escape(x.created_at)+'</td><td>'+escape(x.email)+'<br>#'+escape(x.user_id)+'</td><td>'+escape(x.ip)+'<br>'+escape(x.country_code)+'</td><td>'+(x.is_proxy?'<span class="badge">代理</span> ':'')+(x.fraud_score>=70?'<span class="badge risk-badge">'+escape(x.fraud_score)+'</span>':escape(x.fraud_score))+'</td><td class="user-agent" title="'+escape(x.user_agent)+'">'+escape(x.user_agent)+'</td><td>'+escape(x.reason)+'</td><td>'+(x.masked?'<span class="badge">已伪装</span>':'原始域名')+'</td></tr>').join('');total=d.logs.total;page=d.logs.page;state.hidden=true;table.hidden=false;pageText.textContent='第 '+page+' 页 / 共 '+Math.max(1,Math.ceil(total/size))+' 页';document.querySelector('#prev').disabled=page===1;document.querySelector('#next').disabled=page*size>=total}
f.addEventListener('submit',e=>{e.preventDefault();page=1;load()});document.querySelector('#prev').onclick=()=>{if(page>1){page--;load()}};document.querySelector('#next').onclick=()=>{if(page*size<total){page++;load()}};document.querySelector('#logout').onclick=async()=>{await fetch(logoutUrl,{method:'POST',credentials:'same-origin'});location.reload()};load();
</script></body></html>
